#include <iostream>
#include <memory>

class Buffer {
public:
    Buffer() : data(std::make_unique<int>(7)) {}
    Buffer(const Buffer&) = delete;
    Buffer& operator=(const Buffer&) = delete;
    Buffer(Buffer&&) = default;
    Buffer& operator=(Buffer&&) = default;
    int value() const { return *data; }
private:
    std::unique_ptr<int> data;
};

int main() {
    Buffer a;
    Buffer b = std::move(a);
    std::cout << b.value() << "\n";
    return 0;
}

